ids = [p['id'] for p in projects]
capital = {p['id']: p['capital'] for p in projects}
npv = {p['id']: p['npv'] for p in projects}
if set(range(1, 111)) != set(ids):
    raise ValueError('Project IDs must cover 1..110 exactly.')
m = gp.Model('project_selection')
x = m.addVars(ids, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((npv[i] * x[i] for i in ids)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((capital[i] * x[i] for i in ids)) <= 1000, name='budget')
m.addConstr(x[4] + x[7] <= 1, name='mutual')
m.addConstr(x[6] <= x[1], name='prereq')
m.addConstr(x[10] <= x[5], name='contingent')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for i in ids:
        print(f'x[{i}]: {x[i].X}')
else:
    print(f'Solver status: {m.Status}')